import React from 'react';
import { useNavigate } from 'react-router-dom';

const CustomNav = () => {
    const navigate = useNavigate();

    const handleLogout = () => {
        // Clear any stored user data, if necessary
        localStorage.setItem('user', ''); // Example: remove user data from localStorage
        navigate('/logout'); // Redirect to the logout route
    };

    return (
        <div>
            <nav className="navbar bg-body-tertiary sticky-top">
                <div className="container-fluid">
                    <a className="navbar-brand">StockRoute</a>
                    <form className="d-flex" role="search">
                        <input 
                            className="form-control me-2" 
                            type="search" 
                            placeholder="Search" 
                            aria-label="Search" 
                        />
                        <button className="btn btn-outline-success" type="submit">Search</button>
                        <button className="btn btn-outline-success" type="button" onClick={handleLogout}>Logout</button>
                    </form>
                </div>
            </nav>
        </div>
    );
};

export default CustomNav;
